// The sounds.txt Index of the speech of string id `line`, 0 when the line is not spoken.
inline int speechSound(uint32_t line) {
    const auto found=std::lower_bound(std::begin(npcSpeech),std::end(npcSpeech),line,[](const SpeechLine& s,uint32_t id){return s.line<id;});
    return found!=std::end(npcSpeech)&&found->line==line?found->sound:0;
}
